from pysat.solvers import Glucose4
from pysat.card import CardEnc
import itertools

n = 27
solver = Glucose4()

def edge_var(u, v):
    if u > v:
        u, v = v, u
    return u * n + v + 1

# Degree constraints
for i in range(n):
    edges = []
    for j in range(n):
        if i != j:
            edges.append(edge_var(i, j))

    # Degree >= 3
    cnf = CardEnc.atleast(lits=edges, bound=3, vpool=None)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    # Degree <= 5
    cnf = CardEnc.atmost(lits=edges, bound=5, vpool=None)
    for clause in cnf.clauses:
        solver.add_clause(clause)

# No cycles of length 3
for c in itertools.combinations(range(n), 3):
    solver.add_clause([-edge_var(c[0], c[1]), -edge_var(c[1], c[2]), -edge_var(c[0], c[2])])

# No cycles of length 4
for c in itertools.combinations(range(n), 4):
    for p in itertools.permutations(c):
        if p[0] < p[1] and p[0] < p[3] and p[1] < p[3]:
            solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[0])])

print("Constraints added. Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    edges = []
    for u in range(n):
        for v in range(u + 1, n):
            if model[edge_var(u, v) - 1] > 0:
                edges.append((u, v))
    print(edges)
else:
    print("UNSAT")

from pysat.solvers import Glucose4
from pysat.card import CardEnc
from pysat.formula import IDPool
import itertools

n = 27
solver = Glucose4()
vpool = IDPool()

def edge_var(u, v):
    if u > v:
        u, v = v, u
    return vpool.id(f"e_{u}_{v}")

# Degree constraints
for i in range(n):
    edges = []
    for j in range(n):
        if i != j:
            edges.append(edge_var(i, j))

    # Degree >= 3
    cnf = CardEnc.atleast(lits=edges, bound=3, vpool=vpool)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    # Degree <= 5
    cnf = CardEnc.atmost(lits=edges, bound=5, vpool=vpool)
    for clause in cnf.clauses:
        solver.add_clause(clause)

# No cycles of length 3
for c in itertools.combinations(range(n), 3):
    solver.add_clause([-edge_var(c[0], c[1]), -edge_var(c[1], c[2]), -edge_var(c[0], c[2])])

# No cycles of length 4
for c in itertools.combinations(range(n), 4):
    for p in itertools.permutations(c):
        if p[0] < p[1] and p[0] < p[3] and p[1] < p[3]:
            solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[0])])

# No cycles of length 5
for c in itertools.combinations(range(n), 5):
    for p in itertools.permutations(c):
        # To avoid duplicate cycles, fix the first element to be the minimum,
        # and the second element to be less than the last element.
        if p[0] == min(p) and p[1] < p[4]:
            solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[4]), -edge_var(p[4], p[0])])

print("Constraints added. Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    edges = []
    for u in range(n):
        for v in range(u + 1, n):
            if model[edge_var(u, v) - 1] > 0:
                edges.append((u, v))
    print(edges)
else:
    print("UNSAT")

import networkx as nx

edges = [(0, 9), (0, 12), (0, 20), (0, 21), (0, 24), (1, 11), (1, 15), (1, 17), (1, 18), (1, 25), (2, 6), (2, 8), (2, 22), (2, 24), (3, 8), (3, 10), (3, 16), (3, 19), (3, 23), (4, 13), (4, 14), (4, 17), (4, 21), (5, 6), (5, 14), (5, 20), (6, 7), (6, 18), (7, 12), (7, 13), (8, 17), (9, 18), (9, 19), (10, 11), (10, 20), (11, 22), (12, 15), (13, 19), (14, 16), (15, 16), (21, 26), (22, 26), (23, 25), (23, 26), (24, 25)]

G = nx.Graph()
G.add_edges_from(edges)

def get_girth(G):
    girth = float('inf')
    for n in G.nodes():
        # BFS to find shortest cycle
        queue = [(n, [n])]
        visited = {n: [n]}
        while queue:
            curr, path = queue.pop(0)
            for neighbor in G.neighbors(curr):
                if neighbor not in path:
                    new_path = path + [neighbor]
                    visited[neighbor] = new_path
                    queue.append((neighbor, new_path))
                elif len(path) > 2 and neighbor == path[0]:
                    girth = min(girth, len(path))
    return girth

print("Girth:", get_girth(G))
